def populate_author_roles(apps, schema_editor):
    database = schema_editor.connection.alias
    app_label, model_name = settings.AUTH_USER_MODEL.split(".")
    User = apps.get_model(app_label, model_name)
    role_users = {"Department": [], "Lecturer": [], "Student": []}
    models_to_update = [
        apps.get_model("announcements", model_name)
        for model_name in ("ForumQuestion", "ForumReply")
    ]
    author_ids = set()
    for Model in models_to_update:
        author_ids.update(
            Model.objects.using(database)
            .filter(author_id__isnull=False)
            .values_list("author_id", flat=True)
        )

    author_ids = iter(author_ids)
    while batch := list(islice(author_ids, 1000)):
        for user_id, is_staff, is_superuser in (
            User.objects.using(database)
            .filter(pk__in=batch)
            .values_list("pk", "is_staff", "is_superuser")
        ):
            if is_superuser:
                role_users["Department"].append(user_id)
            elif is_staff:
                role_users["Lecturer"].append(user_id)
            else:
                role_users["Student"].append(user_id)

    for Model in models_to_update:
        for role, user_ids in role_users.items():
            if user_ids:
                Model.objects.using(database).filter(
                    author_id__in=user_ids
                ).update(author_role=role)


